import React from 'react';
import { Slot } from '@radix-ui/react-slot';
import { buttonGroupStyleKeys, getButtonGroupStyleKeys } from '../lib/core';
import type { ButtonGroupBaseProps, ButtonGroupTextBaseProps, ButtonGroupSeparatorBaseProps } from '../lib/core';
import styles from './button-group.module.scss';

export interface ButtonGroupProps extends React.HTMLAttributes<HTMLDivElement>, ButtonGroupBaseProps {}

const ButtonGroup = React.forwardRef<HTMLDivElement, ButtonGroupProps>(({ className = '', variant = 'default', size = 'default', asChild = false, children, ...props }, ref) => {
	const Comp = asChild ? Slot : 'div';
	const styleKeys = getButtonGroupStyleKeys(variant, size);
	const classes = [styles[styleKeys.base], styles[styleKeys.variant], styles[styleKeys.size], className].filter(Boolean).join(' ');

	return (
		<Comp ref={ref} role="group" data-slot="button-group" data-variant={variant} data-size={size} className={classes} {...props}>
			{children}
		</Comp>
	);
});
ButtonGroup.displayName = 'ButtonGroup';

export interface ButtonGroupTextProps extends React.HTMLAttributes<HTMLDivElement>, ButtonGroupTextBaseProps {}

const ButtonGroupText = React.forwardRef<HTMLDivElement, ButtonGroupTextProps>(({ className = '', asChild = false, children, ...props }, ref) => {
	const Comp = asChild ? Slot : 'div';

	return (
		<Comp ref={ref} className={`${styles[buttonGroupStyleKeys.text]} ${className}`} {...props}>
			{children}
		</Comp>
	);
});
ButtonGroupText.displayName = 'ButtonGroupText';

export interface ButtonGroupSeparatorProps extends React.HTMLAttributes<HTMLDivElement>, ButtonGroupSeparatorBaseProps {}

const ButtonGroupSeparator = React.forwardRef<HTMLDivElement, ButtonGroupSeparatorProps>(({ className = '', ...props }, ref) => {
	return <div ref={ref} role="none" aria-hidden="true" data-slot="button-group-separator" className={`${styles[buttonGroupStyleKeys.separator]} ${className}`} {...props} />;
});
ButtonGroupSeparator.displayName = 'ButtonGroupSeparator';

export { ButtonGroup, ButtonGroupText, ButtonGroupSeparator };
export default ButtonGroup;

@use '../../../styles/variables/colors' as *;

.buttonGroup {
	display: flex;
	width: fit-content;
	align-items: stretch;

	> * {
		&:focus-visible {
			position: relative;
			z-index: 1;
		}
	}

	// 直接子元素之间的连接样式
	> *:not(:first-child) {
		border-left: none;
		border-top-left-radius: 0;
		border-bottom-left-radius: 0;
	}

	> *:not(:last-child) {
		border-top-right-radius: 0;
		border-bottom-right-radius: 0;
	}

	// 嵌套按钮组
	[data-slot='button-group'] {
		gap: $spacing-2;
	}

	// 样式变体
	&.variantDefault {
		border: none;
	}

	&.variantOutline {
		border: 1px solid $border;
		border-radius: $radius;
	}

	&.variantGhost {
		border: none;
		background-color: transparent;
	}

	// 尺寸变体
	&.sizeDefault {
		min-height: 2.25rem;
	}

	&.sizeSm {
		min-height: 2rem;
	}

	&.sizeLg {
		min-height: 2.5rem;
	}

	&.sizeIcon {
		min-height: 2.25rem;
	}
}

.text {
	display: flex;
	align-items: center;
	gap: $spacing-2;
	border-radius: $radius;
	border: 1px solid $border;
	background-color: $muted;
	padding: 0 $spacing-4;
	font-size: $text-sm;
	font-weight: $font-medium;
	box-shadow: $shadow-sm;

	svg {
		pointer-events: none;
		width: 1rem;
		height: 1rem;
	}
}

.separator {
	position: relative;
	align-self: stretch;
	margin: 0;
	height: auto;
	width: 1px;
	background-color: $input;
}
